    unet = self.unet_being_trained

    optimizer = getattr(self, f'optim{index}')
    scaler = getattr(self, f'scaler{index}')
    scheduler = getattr(self, f'scheduler{index}')
    warmup_scheduler = getattr(self, f'warmup{index}')

